import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 size 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 이미 마감 또는 승인된 본예산은 편성 대상 목록에서 제외한다
const LOCKED_STATUSES = ['마감', '승인'];

const COUNT_TARGETS_SQL = `
  SELECT COUNT(*) AS total
  FROM budget_item bi
  CROSS JOIN project p
  WHERE p.use_status = '사용'
    AND (CAST(:projectId AS bigint) IS NULL OR p.project_id = CAST(:projectId AS bigint))
    AND (CAST(:budgetGroup AS text) IS NULL OR bi.budget_group = CAST(:budgetGroup AS text))
    AND NOT EXISTS (
      SELECT 1 FROM main_budget mb
      WHERE mb.project_id = p.project_id
        AND mb.budget_item_id = bi.budget_item_id
        AND mb.status IN ('마감', '승인')
        AND (CAST(:accountingUnit AS text) IS NULL OR mb.accounting_unit = CAST(:accountingUnit AS text))
        AND (CAST(:fiscalYear AS integer) IS NULL OR mb.fiscal_year = CAST(:fiscalYear AS integer))
    )
`;

const SELECT_TARGETS_SQL = `
  SELECT bi.budget_item_id AS "budgetItemId",
         bi.item_code AS "itemCode",
         bi.item_name AS "itemName",
         bi.budget_group AS "budgetGroup",
         p.project_id AS "projectId",
         p.project_name AS "projectName"
  FROM budget_item bi
  CROSS JOIN project p
  WHERE p.use_status = '사용'
    AND (CAST(:projectId AS bigint) IS NULL OR p.project_id = CAST(:projectId AS bigint))
    AND (CAST(:budgetGroup AS text) IS NULL OR bi.budget_group = CAST(:budgetGroup AS text))
    AND NOT EXISTS (
      SELECT 1 FROM main_budget mb
      WHERE mb.project_id = p.project_id
        AND mb.budget_item_id = bi.budget_item_id
        AND mb.status IN ('마감', '승인')
        AND (CAST(:accountingUnit AS text) IS NULL OR mb.accounting_unit = CAST(:accountingUnit AS text))
        AND (CAST(:fiscalYear AS integer) IS NULL OR mb.fiscal_year = CAST(:fiscalYear AS integer))
    )
  ORDER BY p.project_id, bi.item_code
  LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)
`;

function invalid(message: string): ApiError {
  return new ApiError(422, 'MAIN_BUDGET_INVALID', message);
}

function optText(v: unknown): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  return String(v);
}

function optInt(v: unknown, label: string): number | null {
  const t = optText(v);
  if (t === null) {
    return null;
  }
  if (!/^-?\d+$/.test(t)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값은 정수여야 합니다.');
  }
  return Number(t);
}

function requireInt(v: unknown, label: string): number {
  if (v === undefined || v === null || v === '') {
    throw invalid(label + ' 값은 필수입니다.');
  }
  const t = String(v);
  if (typeof v === 'boolean' || !/^-?\d+$/.test(t)) {
    throw invalid(label + ' 값은 정수여야 합니다.');
  }
  return Number(t);
}

function requireAmount(v: unknown): string {
  if (v === undefined || v === null || v === '') {
    throw invalid('신청금액은 필수입니다.');
  }
  if (typeof v === 'boolean') {
    throw invalid('신청금액은 숫자여야 합니다.');
  }
  const t = String(v).trim();
  if (!/^-?\d+(\.\d+)?$/.test(t)) {
    throw invalid('신청금액은 숫자여야 합니다.');
  }
  if (t.startsWith('-')) {
    throw invalid('신청금액은 0 이상이어야 합니다.');
  }
  return t;
}

function requireDate(v: unknown): string {
  if (v === undefined || v === null || v === '') {
    throw invalid('신청일은 필수입니다.');
  }
  const t = String(v);
  if (!/^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(t)) {
    throw invalid('신청일은 YYYY-MM-DD 형식이어야 합니다.');
  }
  return t;
}

function requireText(v: unknown, label: string, max: number): string {
  if (v === undefined || v === null || String(v).trim() === '') {
    throw invalid(label + ' 값은 필수입니다.');
  }
  const t = String(v).trim();
  if (t.length > max) {
    throw invalid(label + ' 값은 ' + max + '자 이하여야 합니다.');
  }
  return t;
}

@Controller('api/v1')
export class FnSfr00301Controller {
  @Get('/main-budgets/targets')
  async listMainBudgetTargets(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const q = checks.queryOf(req.query);
    const page = optInt(q['page'], 'page') ?? 0;
    let size = optInt(q['size'], 'size') ?? DEFAULT_SIZE;
    if (page < 0 || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page 또는 size 값이 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const filters = {
      accountingUnit: optText(q['accountingUnit']),
      fiscalYear: optInt(q['fiscalYear'], '기수'),
      projectId: optInt(q['projectId'], '프로젝트 ID'),
      budgetGroup: optText(q['budgetGroup']),
    };
    return transaction(async (db) => {
      const items = await db.query(SELECT_TARGETS_SQL, { ...filters, size, offset: page * size });
      const counts = await db.query(COUNT_TARGETS_SQL, filters);
      const total = Number(counts[0]['total']);
      return { items, page, size, total };
    });
  }

  @Post('/main-budgets')
  @HttpCode(200)
  async createMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const params = {
      projectId: requireInt(data['projectId'], '프로젝트 ID'),
      budgetItemId: requireInt(data['budgetItemId'], '예산과목 ID'),
      accountingUnit: requireText(data['accountingUnit'], '회계단위', 50),
      fiscalYear: requireInt(data['fiscalYear'], '기수'),
      requestAmount: requireAmount(data['requestAmount']),
      requestDate: requireDate(data['requestDate']),
      userId: user.id,
    };
    return transaction(async (db) => {
      const projects = await db.query(
        'SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)',
        { projectId: params.projectId },
      );
      if (projects.length === 0) {
        throw invalid('존재하지 않는 프로젝트입니다.');
      }
      const items = await db.query(
        'SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:budgetItemId AS bigint)',
        { budgetItemId: params.budgetItemId },
      );
      if (items.length === 0) {
        throw invalid('존재하지 않는 예산과목입니다.');
      }
      const existing = await db.query(
        `SELECT main_budget_id AS "mainBudgetId", status
         FROM main_budget
         WHERE accounting_unit = CAST(:accountingUnit AS text)
           AND fiscal_year = CAST(:fiscalYear AS integer)
           AND project_id = CAST(:projectId AS bigint)
           AND budget_item_id = CAST(:budgetItemId AS bigint)`,
        params,
      );
      if (existing.length > 0) {
        if (LOCKED_STATUSES.includes(String(existing[0]['status']))) {
          throw new ApiError(409, 'MAIN_BUDGET_CLOSED', '이미 마감된 본예산 과목입니다. 마감취소 후 수정해 주세요.');
        }
        throw new ApiError(409, 'INVALID_STATE', '이미 신청된 본예산 과목입니다. 수정 기능을 이용해 주세요.');
      }
      const rows = await db.query(
        `INSERT INTO main_budget (
           project_id, budget_item_id, requester_id, accounting_unit, fiscal_year,
           request_amount, request_date, status, created_at, updated_at
         ) VALUES (
           CAST(:projectId AS bigint), CAST(:budgetItemId AS bigint), CAST(:userId AS bigint),
           CAST(:accountingUnit AS text), CAST(:fiscalYear AS integer),
           CAST(:requestAmount AS numeric), CAST(:requestDate AS date), '신청', now(), now()
         )
         RETURNING main_budget_id AS "mainBudgetId", status`,
        params,
      );
      return rows[0];
    });
  }

  @Put('/main-budgets/:mainBudgetId')
  async updateMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const idText = req.params['mainBudgetId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(404, 'MAIN_BUDGET_NOT_FOUND', '대상 본예산을 찾을 수 없습니다.');
    }
    const data = checks.inputOf(req.body);
    const requestAmount = requireAmount(data['requestAmount']);
    const requestDate = requireDate(data['requestDate']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status FROM main_budget WHERE main_budget_id = CAST(:id AS bigint) FOR UPDATE',
        { id: idText },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'MAIN_BUDGET_NOT_FOUND', '대상 본예산을 찾을 수 없습니다.');
      }
      if (LOCKED_STATUSES.includes(String(rows[0]['status']))) {
        throw new ApiError(409, 'MAIN_BUDGET_CLOSED', '마감 또는 승인된 본예산은 수정할 수 없습니다. 마감취소 또는 승인취소 후 수정해 주세요.');
      }
      const updated = await db.query(
        `UPDATE main_budget
         SET request_amount = CAST(:requestAmount AS numeric),
             request_date = CAST(:requestDate AS date),
             updated_at = now()
         WHERE main_budget_id = CAST(:id AS bigint)
         RETURNING main_budget_id AS "mainBudgetId", status`,
        { id: idText, requestAmount, requestDate },
      );
      return updated[0];
    });
  }
}

