import { useState } from 'react';
import {
  Band,
  DataTable,
  DateInput,
  DateText,
  Badge,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;
// 수정할 수 있는 상태 (마감·승인은 취소 절차 없이 수정 불가)
const EDITABLE = ['신청', '마감취소', '승인취소'];

const EMPTY_FILTERS: Row = { accountingUnit: '', fiscalYear: '', projectId: '', budgetGroup: '' };

export default function FnSfr00301Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>(EMPTY_FILTERS);
  const [applied, setApplied] = useState<Row>(EMPTY_FILTERS);
  const [pageNo, setPageNo] = useState(0);
  const [target, setTarget] = useState<Row | null>(null);
  const [editing, setEditing] = useState<Row | null>(null);
  const [results, setResults] = useState<Row[]>([]);
  const [unit, setUnit] = useState('');
  const [year, setYear] = useState<number | string>('');
  const [amount, setAmount] = useState<number | string>('');
  const [reqDate, setReqDate] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/main-budgets/targets', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [applied, pageNo, role],
  );

  const totalAmount = results.reduce((sum, r) => sum + Number(r.requestAmount || 0), 0);

  function openCreate(row: Row) {
    setTarget(row);
    setUnit(String(applied.accountingUnit || ''));
    setYear(applied.fiscalYear === '' ? '' : Number(applied.fiscalYear));
    setAmount('');
    setReqDate('');
  }

  function openEdit(row: Row) {
    setEditing(row);
    setAmount(Number(row.requestAmount));
    setReqDate(String(row.requestDate));
  }

  function checkAmountDate() {
    if (amount === '' || Number.isNaN(Number(amount))) {
      throw new Error('신청금액을 숫자로 입력해 주세요.');
    }
    if (!reqDate) {
      throw new Error('신청일을 입력해 주세요.');
    }
  }

  async function submitCreate() {
    if (!target) {
      return;
    }
    if (!unit.trim()) {
      throw new Error('회계단위를 입력해 주세요.');
    }
    if (year === '' || Number.isNaN(Number(year))) {
      throw new Error('기수를 숫자로 입력해 주세요.');
    }
    checkAmountDate();
    const res = await call<Row>('POST', '/main-budgets', role, {
      projectId: target.projectId,
      budgetItemId: target.budgetItemId,
      accountingUnit: unit.trim(),
      fiscalYear: Number(year),
      requestAmount: Number(amount),
      requestDate: reqDate,
    });
    setResults([
      {
        mainBudgetId: res.mainBudgetId,
        status: res.status,
        projectId: target.projectId,
        budgetItemId: target.budgetItemId,
        itemName: target.itemName,
        accountingUnit: unit.trim(),
        fiscalYear: Number(year),
        requestAmount: Number(amount),
        requestDate: reqDate,
      },
      ...results,
    ]);
    notify('본예산을 신청했습니다.');
    setTarget(null);
    reload();
  }

  async function submitEdit() {
    if (!editing) {
      return;
    }
    checkAmountDate();
    const res = await call<Row>('PUT', '/main-budgets/' + editing.mainBudgetId, role, {
      requestAmount: Number(amount),
      requestDate: reqDate,
    });
    setResults(
      results.map((r) =>
        r.mainBudgetId === editing.mainBudgetId
          ? { ...r, status: res.status, requestAmount: Number(amount), requestDate: reqDate }
          : r,
      ),
    );
    notify('본예산 신청정보를 수정했습니다.');
    setEditing(null);
  }

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>편성 대상</h2>
        <Num value={data ? data.total : 0} />
      </section>
      <section className='box span-4'>
        <h2>이번 신청 건수</h2>
        <Num value={results.length} />
      </section>
      <section className='box span-4'>
        <h2>이번 신청 금액</h2>
        <Num value={totalAmount} />
      </section>

      <section className='box span-8'>
        <h2>편성 대상 예산</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setApplied(draft);
          }}
          onReset={() => {
            setDraft(EMPTY_FILTERS);
            setApplied(EMPTY_FILTERS);
            setPageNo(0);
          }}
        >
          <Field label='회계단위'>
            <TextInput value={draft.accountingUnit} onChange={(v) => setDraft({ ...draft, accountingUnit: v })} />
          </Field>
          <Field label='기수(회계연도)'>
            <NumberInput value={draft.fiscalYear} onChange={(v) => setDraft({ ...draft, fiscalYear: v })} />
          </Field>
          <Field label='프로젝트'>
            <LookupSelect
              table='project'
              role={role}
              value={draft.projectId}
              onChange={(v) => setDraft({ ...draft, projectId: v })}
            />
          </Field>
          <Field label='예산그룹'>
            <TextInput value={draft.budgetGroup} onChange={(v) => setDraft({ ...draft, budgetGroup: v })} />
          </Field>
        </Filters>
        {error ? <p>{error}</p> : null}
        <Band total={data ? data.total : 0} />
        <DataTable
          rows={data ? data.items : []}
          empty='편성 대상 예산이 없습니다.'
          columns={[
            { key: 'itemCode', label: '예산과목 코드' },
            { key: 'itemName', label: '예산과목 명칭' },
            { key: 'budgetGroup', label: '예산그룹' },
            { key: 'projectName', label: '프로젝트 명칭' },
            {
              key: 'action',
              label: '처리',
              render: (row) => (
                <button type='button' onClick={() => openCreate(row)}>
                  본예산 신청
                </button>
              ),
            },
          ]}
        />
        <Pager page={pageNo} size={SIZE} total={data ? data.total : 0} onPage={setPageNo} />
      </section>

      <section className='box span-4'>
        <h2>신청 결과</h2>
        <DataTable
          rows={results}
          empty='신청한 내역이 없습니다.'
          columns={[
            { key: 'itemName', label: '예산과목' },
            { key: 'requestAmount', label: '신청금액', render: (r) => <Num value={r.requestAmount} /> },
            { key: 'status', label: '상태', render: (r) => <Badge value={r.status} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                EDITABLE.includes(String(r.status)) ? (
                  <button type='button' onClick={() => openEdit(r)}>
                    수정
                  </button>
                ) : null,
            },
          ]}
        />
      </section>

      {target ? (
        <Drawer title='본예산 신청' onClose={() => setTarget(null)}>
          <Pairs
            items={[
              ['프로젝트', <RefName table='project' role={role} value={target.projectId} />],
              ['예산과목', <RefName table='budget_item' role={role} value={target.budgetItemId} />],
              ['예산그룹', String(target.budgetGroup)],
            ]}
          />
          <Form onSubmit={submitCreate} submit='신청'>
            <Field label='회계단위' required>
              <TextInput value={unit} onChange={setUnit} />
            </Field>
            <Field label='기수(회계연도)' required>
              <NumberInput value={year} onChange={setYear} />
            </Field>
            <Field label='신청금액' required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label='신청일' required>
              <DateInput value={reqDate} onChange={setReqDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {editing ? (
        <Drawer title='본예산 신청정보 수정' onClose={() => setEditing(null)}>
          <Pairs
            items={[
              ['프로젝트', <RefName table='project' role={role} value={editing.projectId} />],
              ['예산과목', <RefName table='budget_item' role={role} value={editing.budgetItemId} />],
              ['회계단위', String(editing.accountingUnit)],
              ['기수(회계연도)', String(editing.fiscalYear)],
              ['신청일', <DateText value={editing.requestDate} />],
            ]}
          />
          <Form onSubmit={submitEdit} submit='수정'>
            <Field label='신청금액' required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label='신청일' required>
              <DateInput value={reqDate} onChange={setReqDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
